def esc(v):return html.escape(str(v))
def text(x,y,s,size=18,anchor='middle'):
    return f'<text x="{x:g}" y="{y:g}" text-anchor="{anchor}" font-family="Arial,sans-serif" font-size="{size}" fill="#111">{esc(s)}</text>'
def ln(x,y,u,v,dash=False,w=2):
    return f'<path d="M{x:g} {y:g}L{u:g} {v:g}" fill="none" stroke="#111" stroke-width="{w:g}"'+(' stroke-dasharray="7 5"' if dash else '')+'/>'
def circle(x,y,r=5,fill='white'):
    return f'<circle cx="{x:g}" cy="{y:g}" r="{r:g}" fill="{fill}" stroke="#111" stroke-width="2"/>'
def arr(x,y,u,v,dash=False):
    a=math.atan2(v-y,u-x);b=ln(x,y,u,v,dash)
    return b+f'<path d="M{u:g} {v:g}L{u-12*math.cos(a)+5*math.sin(a):g} {v-12*math.sin(a)-5*math.cos(a):g}L{u-12*math.cos(a)-5*math.sin(a):g} {v-12*math.sin(a)+5*math.cos(a):g}Z" fill="#111"/>'
def box(x,y,w,h,labels):
    b=f'<rect x="{x:g}" y="{y:g}" width="{w:g}" height="{h:g}" rx="9" fill="white" stroke="#111" stroke-width="2"/>'
    lines=labels if isinstance(labels,list) else [labels]
    for i,t in enumerate(lines):b+=text(x+w/2,y+h/2+(i-(len(lines)-1)/2)*24+6,t,17)
    return b
def svg(body,title):
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 560" role="img" aria-label="'+esc(title)+'"><rect width="900" height="560" fill="white"/>'+text(450,30,title,21)+body+'</svg>'
def graph(title,series,xr,yr,xlabel,ylabel,xticks=None,yticks=None,errors=None):
    X=lambda x:115+660*(x-xr[0])/(xr[1]-xr[0]);Y=lambda y:440-325*(y-yr[0])/(yr[1]-yr[0])
    b=ln(115,105,115,440)+ln(115,440,790,440)+text(450,526,xlabel,18)
    b+='<text x="28" y="280" transform="rotate(-90 28 280)" text-anchor="middle" font-family="Arial,sans-serif" font-size="18">'+esc(ylabel)+'</text>'
    xticks=xticks if xticks is not None else [xr[0]+i*(xr[1]-xr[0])/4 for i in range(5)]
    yticks=yticks if yticks is not None else [yr[0]+i*(yr[1]-yr[0])/4 for i in range(5)]
    for x in xticks:b+=ln(X(x),440,X(x),447)+text(X(x),475,f'{x:g}',16)
    for y in yticks:b+=ln(108,Y(y),115,Y(y))+text(98,Y(y)+6,f'{y:g}',16,'end')
    if yr[0]<0<yr[1]:b+=ln(115,Y(0),775,Y(0),True)
    for j,(name,pts) in enumerate(series):
        dash=j%3!=0
        pattern=['','8 5','2 5'][j%3]
        b+='<polyline points="'+' '.join(f'{X(x):.3f},{Y(y):.3f}' for x,y in pts)+'" fill="none" stroke="#111" stroke-width="2.3"'+(f' stroke-dasharray="{pattern}"' if pattern else '')+'/>'
        if len(pts)<25:
            for x,y in pts:b+=circle(X(x),Y(y),4,'white' if dash else '#111')
        if name:
            bx=135+j*230
            legend=ln(bx,72,bx+34,72,dash)
            if pattern:legend=legend.replace('7 5',pattern)
            b+=legend+text(bx+44,78,name,16,'start')
    if errors:
        for x,y,e in errors:
            b+=ln(X(x),Y(y-e),X(x),Y(y+e))+ln(X(x)-6,Y(y-e),X(x)+6,Y(y-e))+ln(X(x)-6,Y(y+e),X(x)+6,Y(y+e))
    return svg(b,title)
def bars(title,labels,values,ylabel,maximum=None):
    m=maximum or max(values)*1.22;X=lambda i:145+(i+.5)*610/len(values);Y=lambda y:430-300*y/m
    b=ln(115,115,115,430)+ln(115,430,790,430)
    b+='<text x="28" y="280" transform="rotate(-90 28 280)" text-anchor="middle" font-family="Arial,sans-serif" font-size="18">'+esc(ylabel)+'</text>'
    for k in range(5):
        y=m*k/4;b+=ln(108,Y(y),115,Y(y))+text(98,Y(y)+6,f'{y:g}',16,'end')
    bw=min(72,430/len(values))
    for i,(lab,v) in enumerate(zip(labels,values)):
        x=X(i);b+=f'<rect x="{x-bw/2:g}" y="{Y(v):g}" width="{bw:g}" height="{430-Y(v):g}" fill="#eee" stroke="#111" stroke-width="2"/>'
        b+=text(x,Y(v)-12,f'{v:g}',17)
        lines=lab.split('|')
        for k,t in enumerate(lines):b+=text(x,463+23*k,t,16)
    return svg(b,title)
def pathway(title,nodes,edges,notes=()):
    b=''
    for a,z,label in edges:
        x,y,w,h,_=nodes[a];u,v,ww,hh,_=nodes[z]
        if abs(v-y)<40:
            sx,sy,tx,ty=(x+w,y+h/2,u,v+hh/2) if u>x else (x,y+h/2,u+ww,v+hh/2)
        else:
            sx,sy,tx,ty=(x+w/2,y+h,u+ww/2,v) if v>y else (x+w/2,y,u+ww/2,v+hh)
        b+=arr(sx,sy,tx,ty)
        if label:
            ly=(sy+ty)/2-12
            if abs(v-y)<40 and len(label)>12:ly=min(y,v)-18
            lx=(sx+tx)/2
            if abs(v-y)>=40:lx+=80;ly=(sy+ty)/2
            b+=text(lx,ly,label,16)
    for x,y,w,h,lab in nodes:b+=box(x,y,w,h,lab)
    for i,n in enumerate(notes):b+=text(450,495+i*25,n,17)
    return svg(b,title)
def membrane(title,top,bottom,kind='mitochondrion',labels=('X','Y')):
    b=text(450,95,top,21)+text(450,445,bottom,21)
    b+='<rect x="90" y="205" width="720" height="80" fill="#eee" stroke="#111" stroke-width="2"/>'
    for x in range(105,800,25):
        b+=circle(x,215,6)+circle(x,275,6)+ln(x-3,222,x-6,247,w=1)+ln(x+3,222,x+6,247,w=1)+ln(x-3,268,x-6,250,w=1)+ln(x+3,268,x+6,250,w=1)
    b+=box(190,185,115,120,[])+box(580,185,115,120,[])+text(280,250,labels[0],19)+text(673,250,labels[1],19)
    if kind=='mitochondrion':
        b+=arr(247,350,247,145)+arr(637,145,637,300)+text(190,365,'H+',19)+text(697,365,'H+',19)
        b+=circle(638,330,27)+text(638,336,'head',14)
    elif kind=='chloroplast':
        b+=arr(247,145,247,350)+arr(637,350,637,190)+text(180,155,'H+',19)+text(700,155,'H+',19)
        b+=circle(638,160,27)+text(638,166,'head',14)
    return svg(b,title)
def ck(label,a,e,tol=1e-8):
    assert math.isclose(a,e,abs_tol=tol,rel_tol=tol),(label,a,e)
    return {'label':label,'actual':a,'expected':e,'status':'passed'}
def yes(label,value):
    assert value,label
    return {'label':label,'actual':bool(value),'expected':True,'status':'passed'}
def M(s):return ('M1',s)
def A(s):return ('A1',s)
def R(s):return ('R1',s)
def P(prompt,*steps):return (prompt,steps)
def add(n,title,code,statements,stem,parts,diagram,checks,biology,summary,kind='data-based'):
    pp=[];ms=[]
    for i,(prompt,steps) in enumerate(parts):
        lab=chr(97+i);pp.append({'label':lab,'prompt':prompt,'marks':len(steps)})
        ms.append({'part':lab,'steps':[{'code':c,'text':s} for c,s in steps]})
    q={'id':f'ib-bio-c-{n}','number':n,'subject':'biology','topicId':'interaction-interdependence','collectionId':'biology-interaction-interdependence','subtopic':SUB[code],'syllabusCode':code,'level':'sl' if n<=720 else 'ahl','title':title,'difficulty':'hard','calculator':True,'questionType':kind,'stem':stem+'\n\nAll data are constructed for this original practice question; diagrams are schematic, not micrographs. Give non-exact numerical answers to three significant figures unless stated otherwise.','parts':pp,'markScheme':ms,'marks':sum(p['marks'] for p in pp),'diagramSvg':diagram,'diagramCaption':'Original constructed data or biological schematic; use with the stated assumptions.','answerSummary':summary,'source':{'document':'Independent syllabus-authored practice','question':n},'verification':{'method':'Original first-assessment-2025 syllabus authoring, executable numerical checks, per-question biological and SVG review.','notes':'Statements: '+statements+'. '+biology+' M/A/R are instructional point labels, not official IB markscheme notation. Accept valid equivalent biological explanations; apply follow-through only to biologically admissible earlier results.'},'status':'published'}
    assert code!='C2.1' or q['level']=='ahl'
    assert 6<=q['marks']<=14 and len(parts)>=2
    ET.fromstring(diagram);assert len(diagram)<300000
    assert not re.search(r'<(?:script|foreignObject|image|style|animate)|(?:href|src)=|url\s*\(|\bon\w+\s*=',diagram,re.I)
    Q.append(q);REV.append({'id':q['id'],'status':'passed','statements':statements,'level':q['level'],'checks':checks,'biologicalReview':biology,'marks':q['marks']})

# Shared SL/HL: 20 unique investigations and applications.
add(701,'Separating a detector delay from an enzyme’s initial rate','C1.1','C1.1.5–10',
'A product detector has a known 10 s mixing delay. After that delay, enzyme X gives product concentrations 0, 12, 24, 35 and 43 µmol dm−3 at times 10, 20, 30, 40 and 60 s. A no-enzyme control remains at zero. The last substrate concentration is much lower than the initial concentration.',
[P('Calculate the initial rate using the first reliable 20 s interval and compare it with the mean rate from 10 to 60 s.',M('Use Δproduct/Δtime over 10–30 s: (24−0)/(30−10).'),A('Initial rate = 1.20 µmol dm−3 s−1.'),A('The 10–60 s mean is 43/50 = 0.860 µmol dm−3 s−1, lower than the initial rate.')),
 P('Explain the decreasing slope without assuming that X is being consumed.',R('Substrate depletion reduces the frequency of productive substrate–active-site encounters.'),R('The enzyme is regenerated after catalysis; fewer substrate molecules can lower rate without lowering enzyme amount.')),
 P('Design a comparison of X at two temperatures that distinguishes a temperature effect from the detector delay.',R('Equilibrate enzyme and substrate separately at each temperature, then mix using the same measured timing protocol.'),R('Use equal enzyme/substrate concentrations, pH and volume and compare slopes over the same post-mixing initial interval.'),R('Use independent replicate reaction mixtures and report their spread; include no-enzyme controls at both temperatures.'))],
graph('Product accumulation after mixing',[('Enzyme X',[(10,0),(20,12),(30,24),(40,35),(60,43)]),('No enzyme',[(10,0),(60,0)])],(0,60),(0,48),'Time / s','Product / µmol dm−3'),
[ck('Initial slope',24/20,1.2),ck('Long interval slope',43/50,.86)],'Rate is an initial slope after instrument delay; substrate depletion is distinct from enzyme consumption. No HL inhibition classification is required.','Initial 1.20 versus mean 0.860 µmol dm−3 s−1; use controlled replicated initial-rate comparisons.')

add(702,'Recovery after pH treatment is different from recovery after heating','C1.1','C1.1.7–9',
'Identical enzyme samples are pretreated, then all are assayed at pH 7 and 25°C with excess substrate. Untreated control activities are 98, 100 and 102 units. Samples pretreated at pH 3 give 76, 80 and 84 units after neutralization. Samples heated at 80°C give 3, 4 and 5 units after cooling. One unit is the same product rate in every assay.',
[P('Calculate mean recovered activity as a percentage of the control for each pretreatment.',M('Control mean = 100; pH-treated mean = 80; heated mean = 4.'),A('Recovered activities are 80.0% and 4.00%, respectively.')),
 P('Explain why the assay conditions and recovery result matter when interpreting denaturation.',R('Assaying all samples at the same pH and temperature removes immediate assay-condition differences.'),R('Persistent loss after cooling is consistent with heat-induced disruption of the protein’s functional conformation and active site.'),R('Substantial recovery after neutralization shows that low activity at pH 3 need not imply irreversible destruction; altered charges/interactions can be partly reversible.')),
 P('Evaluate the claim that all molecules in the pH-treated sample are undamaged.',R('The sample mean remains 20% below the control, so full recovery of the preparation is not demonstrated.'),R('A mean activity cannot identify whether every molecule has lower activity or some molecules are inactive.'),R('Use more independent samples and recovery-time measurements; the three replicates show variability but do not by themselves establish statistical significance.'))],
bars('Activity after return to common assay conditions',['Control','pH 3 then|neutralized','80°C then|cooled'],[100,80,4],'Mean activity / units',120),
[ck('pH treatment mean',statistics.mean([76,80,84]),80),ck('Heated mean',statistics.mean([3,4,5]),4)],'Assay recovery distinguishes temporary pH effects from persistent conformational loss. Variation is not treated as a significance test.','80.0% and 4.00% recovered activity; neither a sample mean nor three replicates proves every molecule is intact.')

